package main

import "encoding/base64"

var bootstrapAssetsBase64 = map[string]string{
	"tickets/README.md":       "",
	"tickets/spec-erg-v1.md":  "",
	"tickets/integration.md": "",
}

func bootstrapAsset(path string) (string, bool) {
	b64, ok := bootstrapAssetsBase64[path]
	if !ok {
		return "", false
	}
	data, err := base64.StdEncoding.DecodeString(b64)
	if err != nil {
		return "", false
	}
	return string(data), true
}
